30	
31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	
43	    @Column(name = "title")
44	    private String title;
45	
46	    @Column(name = "address")
47	    @NotEmpty
48	    private String address;
49	
50	    @Column(name = "address_line1")
51	    private String addressLine1;
52	
53	    @Column(name = "address_line2")
54	    private String addressLine2;
55	
56	    @Column(name = "city")
57	    @NotEmpty
58	    private String city;
59	
60	    @Column(name = "telephone")
61	    @NotEmpty
62	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
63	    private String telephone;
64	
65	    @Column(name = "email")
66	    @Email
67	    private String email;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "postcode")
85	    private String postcode;
86	
87	    /**
88	     * Whether this owner was flagged as a suspected soft-duplicate of an existing owner. Retained
89	     * as part of the API/persistence contract but always {@code false} under the current
90	     * household-keyed rule: an owner sharing an existing owner's {@code lastName} and
91	     * {@code postcode} is now the same household, so it is either rejected as a household duplicate
92	     * (409) or admitted as a declared {@code sharesHousehold} member — and a declared member is not
93	     * a suspected duplicate. No production code path sets this field.
94	     */
95	    @Column(name = "possible_duplicate")
96	    private boolean possibleDuplicate;
97	
98	    /**
99	     * The id of the existing owner this owner soft-matches, set together with
100	     * {@link #isPossibleDuplicate()}. Retained for contract compatibility but always {@code null}
101	     * under the current household-keyed rule (see {@link #isPossibleDuplicate()}); no production
102	     * code path sets it.
103	     */
104	    @Column(name = "possible_duplicate_of")
105	    private Integer possibleDuplicateOf;
106	
107	    /**
108	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
109	     * household with an existing owner. When {@code true}, creation is allowed even if
110	     * another owner already has the same lastName and address.
111	     */
112	    @Transient
113	    private boolean sharesHousehold;
114	
115	    /**
116	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
117	     * (including this owner), populated by the service when an owner is loaded for presentation.
118	     * Zero when the owner belongs to no household. Used to derive the membership tier.
119	     */
120	    @Transient
121	    private int householdSize;
122	
123	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
124	    private Set<Pet> pets;
125	
126	    public String getTitle() {
127	        return this.title;
128	    }
129	
130	    public void setTitle(String title) {
131	        this.title = title;
132	    }
133	
134	    /**
135	     * The owner's salutation: the {@link #getTitle() title} and {@code lastName} separated by a
136	     * single space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when the owner has no
137	     * title (title null or empty).
138	     */
139	    public String getSalutation() {
140	        if (this.title == null || this.title.isEmpty()) {
141	            return this.getLastName();
142	        }
143	        return this.title + " " + this.getLastName();
144	    }
145	
146	    public String getAddress() {
147	        return this.address;
148	    }
149	
150	    public void setAddress(String address) {
151	        this.address = address;
152	    }
153	
154	    public String getAddressLine1() {
155	        return this.addressLine1;
156	    }
157	
158	    public void setAddressLine1(String addressLine1) {
159	        this.addressLine1 = addressLine1;
160	    }
161	
162	    public String getAddressLine2() {
163	        return this.addressLine2;
164	    }
165	
166	    public void setAddressLine2(String addressLine2) {
167	        this.addressLine2 = addressLine2;
168	    }
169	
170	    public String getCity() {
171	        return this.city;
172	    }
173	
174	    public void setCity(String city) {
175	        this.city = city;
176	    }
177	
178	    public String getTelephone() {
179	        return this.telephone;
180	    }
181	
182	    public void setTelephone(String telephone) {
183	        this.telephone = telephone;
184	    }
185	
186	    /**
187	     * The stored E.164 {@link #getTelephone() telephone} formatted for human display: the
188	     * country code, a space, then the national digits grouped in threes (e.g.
189	     * {@code "+61 412 345 678"}). Null when no telephone is set.
190	     */
191	    public String getTelephoneDisplay() {
192	        return E164Telephone.toDisplay(this.telephone);
193	    }
194	
195	    public String getEmail() {
196	        return this.email;
197	    }
198	
199	    public void setEmail(String email) {
200	        this.email = email;
201	    }
202	
203	    public LocalDate getRegistrationDate() {
204	        return this.registrationDate;
205	    }
206	
207	    public void setRegistrationDate(LocalDate registrationDate) {
208	        this.registrationDate = registrationDate;
209	    }
210	
211	    public LocalDate getBirthDate() {
212	        return this.birthDate;
213	    }
214	
215	    public void setBirthDate(LocalDate birthDate) {
216	        this.birthDate = birthDate;
217	    }
218	
219	    /**
220	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
221	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
222	     * over. Returns null when either the birth date or the registration date is not set.
223	     */
224	    public String getAgeBand() {
225	        if (this.birthDate == null || this.registrationDate == null) {
226	            return null;
227	        }
228	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
229	        if (age < 18) {
230	            return "MINOR";
231	        }
232	        if (age < 65) {
233	            return "ADULT";
234	        }
235	        return "SENIOR";
236	    }
237	
238	    public String getCustomerCode() {
239	        return this.customerCode;
240	    }
241	
242	    public void setCustomerCode(String customerCode) {
243	        this.customerCode = customerCode;
244	    }
245	
246	    public String getHouseholdId() {
247	        return this.householdId;
248	    }
249	
250	    public void setHouseholdId(String householdId) {
251	        this.householdId = householdId;
252	    }
253	
254	    public Integer getNamesakeCount() {
255	        return this.namesakeCount;
256	    }
257	
258	    public void setNamesakeCount(Integer namesakeCount) {
259	        this.namesakeCount = namesakeCount;
260	    }
261	
262	    public String getPostcode() {
263	        return this.postcode;
264	    }
265	
266	    public void setPostcode(String postcode) {
267	        this.postcode = postcode;
268	    }
269	
270	    public boolean isPossibleDuplicate() {
271	        return this.possibleDuplicate;
272	    }
273	
274	    public void setPossibleDuplicate(boolean possibleDuplicate) {
275	        this.possibleDuplicate = possibleDuplicate;
276	    }
277	
278	    public Integer getPossibleDuplicateOf() {
279	        return this.possibleDuplicateOf;
280	    }
281	
282	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
283	        this.possibleDuplicateOf = possibleDuplicateOf;
284	    }
285	
286	    /** The household size at or above which an owner earns the household membership points. */
287	    public static final int MEMBERSHIP_HOUSEHOLD_SIZE = 3;
288	
289	    /** The number of tenure days beyond which an owner earns the tenure membership points. */
290	    public static final long MEMBERSHIP_TENURE_DAYS = 365;
291	
292	    /**
293	     * The owner's membership points, computed from stored fields: they start at 0, gain 2 when an
294	     * email is present, gain 1 when {@code namesakeCount} is 0, gain 2 for a household of
295	     * {@value #MEMBERSHIP_HOUSEHOLD_SIZE} or more (see {@link #getHouseholdSize()}), and gain 3 when
296	     * the owner's tenure (days elapsed since its {@code registrationDate}) exceeds
297	     * {@value #MEMBERSHIP_TENURE_DAYS}.
298	     */
299	    public int getMembershipPoints() {
300	        int points = 0;
301	        if (this.email != null && !this.email.isEmpty()) {
302	            points += 2;
303	        }
304	        if (this.namesakeCount != null && this.namesakeCount == 0) {
305	            points += 1;
306	        }
307	        if (this.householdSize >= MEMBERSHIP_HOUSEHOLD_SIZE) {
308	            points += 2;
309	        }
310	        if (this.registrationDate != null
311	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > MEMBERSHIP_TENURE_DAYS) {
312	            points += 3;
313	        }
314	        return points;
315	    }
316	
317	    /**
318	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()}: 1 for 0-1
319	     * points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
320	     */
321	    public int getMembershipLevel() {
322	        int points = getMembershipPoints();
323	        if (points >= 6) {
324	            return 4;
325	        }
326	        if (points >= 4) {
327	            return 3;
328	        }
329	        if (points >= 2) {
330	            return 2;
331	        }
332	        return 1;
333	    }
334	
335	    /**
336	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
337	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
338	     * key consolidates the former separate telephone, email and household duplicate rules — two
339	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
340	     * part of the key, two members of the same household (same {@code householdId}) with different
341	     * telephones have different keys and are both allowed.
342	     */
343	    public String getIdentityKey() {
344	        String tel = this.telephone == null ? "" : this.telephone;
345	        String mail = this.email == null ? "" : this.email;
346	        String household = this.householdId == null ? "" : this.householdId;
347	        return tel + "|" + mail + "|" + household;
348	    }
349	
350	    /**
351	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
352	     * or null when the {@code customerCode} has not been assigned.
353	     */
354	    public Integer getCheckDigit() {
355	        if (this.customerCode == null) {
356	            return null;
357	        }
358	        int sum = 0;
359	        boolean dbl = true;
360	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
361	            char c = this.customerCode.charAt(i);
362	            if (c < '0' || c > '9') {
363	                continue;
364	            }
365	            int d = c - '0';
366	            if (dbl) {
367	                d *= 2;
368	                if (d > 9) {
369	                    d -= 9;
370	                }
371	            }
372	            sum += d;
373	            dbl = !dbl;
374	        }
375	        return (10 - (sum % 10)) % 10;
376	    }
377	
378	    /**
379	     * The owner's membership number formatted {@code '<customerCode>-M<YY>'} where YY is the last
380	     * two digits of the registration year, or null when either the {@code customerCode} or the
381	     * {@code registrationDate} is not set.
382	     */
383	    public String getMembershipNumber() {
384	        if (this.customerCode == null || this.registrationDate == null) {
385	            return null;
386	        }
387	        String yy = String.format("%02d", this.registrationDate.getYear() % 100);
388	        return this.customerCode + "-M" + yy;
389	    }
390	
391	    public boolean isSharesHousehold() {
392	        return this.sharesHousehold;
393	    }
394	
395	    public void setSharesHousehold(boolean sharesHousehold) {
396	        this.sharesHousehold = sharesHousehold;
397	    }
398	
399	    public int getHouseholdSize() {
400	        return this.householdSize;
401	    }
402	
403	    public void setHouseholdSize(int householdSize) {
404	        this.householdSize = householdSize;
405	    }
406	
407	    protected Set<Pet> getPetsInternal() {
408	        if (this.pets == null) {
409	            this.pets = new HashSet<>();
410	        }
411	        return this.pets;
412	    }
413	
414	    protected void setPetsInternal(Set<Pet> pets) {
415	        this.pets = pets;
416	    }
417	
418	    public List<Pet> getPets() {
419	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
420	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
421	        return Collections.unmodifiableList(sortedPets);
422	    }
423	
424	    public void setPets(List<Pet> pets) {
425	        this.pets = new HashSet<>(pets);
426	    }
427	
428	    public void addPet(Pet pet) {
429	        getPetsInternal().add(pet);
430	        pet.setOwner(this);
431	    }
432	
433	    /**
434	     * Return the Pet with the given name, or null if none found for this Owner.
435	     *
436	     * @param name to test
437	     * @return true if pet name is already in use
438	     */
439	    public Pet getPet(String name) {
440	        return getPet(name, false);
441	    }
442	
443	    /**
444	     * Return the Pet with the given name, or null if none found for this Owner.
445	     *
446	     * @param name to test
447	     * @return true if pet name is already in use
448	     */
449	    public Pet getPet(String name, boolean ignoreNew) {
450	        name = name.toLowerCase();
451	        for (Pet pet : getPetsInternal()) {
452	            if (!ignoreNew || !pet.isNew()) {
453	                String compName = pet.getName();
454	                compName = compName.toLowerCase();
455	                if (compName.equals(name)) {
456	                    return pet;
457	                }
458	            }
459	        }
460	        return null;
461	    }
462	
463	    public Pet getPet(Integer petId) {
464	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
465	    }
466	
467	    @Override
468	    public String toString() {
469	        return new ToStringCreator(this)
470	
471	            .append("id", this.getId())
472	            .append("new", this.isNew())
473	            .append("lastName", this.getLastName())
474	            .append("firstName", this.getFirstName())
475	            .append("address", this.address)
476	            .append("city", this.city)
477	            .append("telephone", this.telephone)
478	            .toString();
479	    }
480	}
