251	    /**
252	     * Rejects saving {@code owner} when it carries a postcode that is out of range for its city's
253	     * region. The postcode is optional: a {@code null} postcode is left untouched. When present it
254	     * is assumed to already be four digits (enforced by request validation); if the owner's city has
255	     * a known region (see {@link Region}), the postcode must fall within that region's range
256	     * ({@link Region#postcodeRange(String)}). A city with no known region accepts any 4-digit
257	     * postcode.
258	     *
259	     * @throws InvalidPostcodeException if the postcode is out of range for the city's region
260	     */
261	    private void assertPostcodeValid(Owner owner) {
262	        String postcode = owner.getPostcode();
263	        if (postcode == null) {
264	            return;
265	        }
266	        String region = Region.forCity(owner.getCity());
267	        int[] range = region == null ? null : Region.postcodeRange(region);
268	        if (range == null) {
269	            return;
270	        }
271	        int value = Integer.parseInt(postcode);
272	        if (value < range[0] || value > range[1]) {
273	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
274	        }
275	    }
276	
277	    /**
278	     * Rejects saving {@code owner} when it carries a {@code registrationDate} later than the current
279	     * server date. The registration date is optional: a {@code null} date is left untouched (it is
280	     * defaulted to today by {@link #saveOwner(Owner)}). A registration cannot be dated in the future.
281	     *
282	     * @throws FutureRegistrationDateException if the supplied registration date is after today
283	     */
284	    private void assertRegistrationDateNotFuture(Owner owner) {
285	        LocalDate registrationDate = owner.getRegistrationDate();
286	        if (registrationDate == null) {
287	            return;
288	        }
289	        LocalDate today = LocalDate.now();
290	        if (registrationDate.isAfter(today)) {
291	            throw new FutureRegistrationDateException(registrationDate, today);
292	        }
293	    }
294	
295	    /** Email domains rejected as disposable/throwaway addresses. */
296	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
297	        "mailinator.com", "tempmail.com", "guerrillamail.com");
298	
299	    /**
300	     * Rejects saving {@code owner} when its email's domain is on the disposable-domain blocklist
301	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The email is optional: a {@code null} email is left
302	     * untouched. The comparison is case-insensitive on the part after the last {@code '@'}; the
303	     * email has already been lower-cased by {@link #saveOwner(Owner)} before this runs.
304	     *
305	     * @throws DisposableEmailDomainException if the email domain is blocklisted
306	     */
307	    private void assertEmailDomainAllowed(Owner owner) {
308	        String email = owner.getEmail();
309	        if (email == null) {
310	            return;
311	        }
312	        int at = email.lastIndexOf('@');
313	        if (at < 0) {
314	            return;
315	        }
316	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
317	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
318	            throw new DisposableEmailDomainException(domain);
319	        }
320	    }
