322	    @Override
323	    @Transactional
324	    public void saveOwner(Owner owner) throws DataAccessException {
325	        assertPostcodeValid(owner);
326	        assertRegistrationDateNotFuture(owner);
327	        if (owner.getTelephone() != null) {
328	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
329	        }
330	        if (owner.getEmail() != null) {
331	            owner.setEmail(normalizeEmail(owner.getEmail()));
332	        }
333	        assertEmailDomainAllowed(owner);
334	        applyAddress(owner);
335	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
336	        owner.setRegistrationDate(rollToBusinessDay(effectiveDate));
337	        if (owner.getCustomerCode() == null) {
338	            owner.setCustomerCode(generateCustomerCode(owner));
339	        }
340	        boolean creating = owner.isNew();
341	        if (creating) {
342	            owner.setNamesakeCount(countNamesakes(owner));
343	            assertDailyCapacity(owner);
344	            assertCityCapacity(owner);
345	        }
346	        assignHouseholdId(owner);
347	        assertIdentityUnique(owner);
348	        if (creating) {
349	            assertHouseholdUnique(owner);
350	        }
351	        ownerRepository.save(owner);
352	        populateHouseholdSize(owner);
353	        if (creating) {
354	            AUDIT.info(
355	                "owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
356	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
357	                owner.getMembershipLevel(), owner.getMembershipNumber());
358	        }
359	    }
360	
361	    /**
362	     * Build a {@code customerCode} formatted {@code '<REGION>-<HASH8>'} where REGION is the region
363	     * code derived from the owner's postcode (see {@link Region#regionForPostcode(String)}) and
364	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the concatenation of
365	     * the owner's normalized telephone and {@code lastName}. The telephone is already normalized by
366	     * {@link #saveOwner(Owner)} before this runs. The {@code '<REGION>-<HASH8>'} layout is read back
367	     * by {@link Region#regionOfCustomerCode(String)}; keep the two in sync.
368	     */
369	    private String generateCustomerCode(Owner owner) {
370	        String region = Region.regionForPostcode(owner.getPostcode());
371	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
372	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
373	        String hash8 = sha256UpperHex(telephone + lastName, 8);
374	        return deduplicateCustomerCode(owner, region + "-" + hash8);
375	    }
376	
377	    /**
378	     * Returns {@code base} unchanged when no other owner already holds it; otherwise appends
379	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that makes the result unique among the
380	     * existing owners' {@code customerCode}s. The {@code owner} being saved is excluded from the
381	     * comparison so re-saving it does not treat its own code as a collision.
382	     */
383	    private String deduplicateCustomerCode(Owner owner, String base) {
384	        Set<String> taken = new HashSet<>();
385	        for (Owner existing : ownerRepository.findAll()) {
386	            if (!existing.getId().equals(owner.getId()) && existing.getCustomerCode() != null) {
387	                taken.add(existing.getCustomerCode());
388	            }
389	        }
390	        if (!taken.contains(base)) {
391	            return base;
392	        }
393	        int n = 2;
394	        while (taken.contains(base + "-" + n)) {
395	            n++;
396	        }
397	        return base + "-" + n;
398	    }
399	
400	    /**
401	     * The first {@code chars} upper-case hex characters of the SHA-256 digest of {@code value}'s
402	     * UTF-8 bytes.
403	     */
404	    private static String sha256UpperHex(String value, int chars) {
405	        try {
406	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
407	            byte[] hash = digest.digest(value.getBytes(StandardCharsets.UTF_8));
408	            StringBuilder sb = new StringBuilder(hash.length * 2);
409	            for (byte b : hash) {
410	                sb.append(String.format("%02X", b));
411	            }
412	            return sb.substring(0, chars);
413	        } catch (NoSuchAlgorithmException e) {
414	            throw new IllegalStateException("SHA-256 not available", e);
415	        }
416	    }
417	
418	    /** Maximum number of owners permitted in a single city. */
419	    private static final long CITY_OWNER_LIMIT = 50L;
420	
421	    /**
422	     * Rejects creating {@code owner} when its city already contains {@link #CITY_OWNER_LIMIT} or
423	     * more owners, so no city can grow beyond the capacity limit.
424	     *
425	     * @throws CityOwnerLimitException if the owner's city is already at capacity
426	     */
427	    private void assertCityCapacity(Owner owner) {
428	        if (owner.getCity() == null) {
429	            return;
430	        }
431	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
432	            throw new CityOwnerLimitException(owner.getCity(), CITY_OWNER_LIMIT);
433	        }
434	    }
435	
436	    /**
437	     * Rolls {@code date} forward to the next business day when it falls on a weekend: a Saturday or
438	     * Sunday becomes the following Monday. Business days (Monday to Friday) are returned unchanged.
439	     */
440	    private static LocalDate rollToBusinessDay(LocalDate date) {
441	        switch (date.getDayOfWeek()) {
442	            case SATURDAY:
443	                return date.plusDays(2);
444	            case SUNDAY:
445	                return date.plusDays(1);
446	            default:
447	                return date;
448	        }
449	    }
450	
451	    /** Maximum number of owners permitted to be registered on a single day. */
452	    private static final long DAILY_OWNER_LIMIT = 100L;
453	
454	    /** More than this many owners registered on a single day raises the bulk-signup warning. */
455	    private static final long BULK_SIGNUP_THRESHOLD = 80L;
456	
457	    /**
458	     * Reports whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered
459	     * today, reusing the same daily accumulation as the per-day create limit ({@link
460	     * #assertDailyCapacity}).
461	     */
462	    @Override
463	    @Transactional(readOnly = true)
464	    public boolean isBulkSignupWarningActive() throws DataAccessException {
465	        return countOwnersRegisteredOn(LocalDate.now()) > BULK_SIGNUP_THRESHOLD;
466	    }
467	
468	    /**
469	     * Rejects creating {@code owner} when its {@code registrationDate} (defaulted to today for a new
470	     * owner) already has {@link #DAILY_OWNER_LIMIT} or more owners registered, so no more than that
471	     * many owners can be created on any single day.
472	     *
473	     * @throws DailyOwnerLimitException if the owner's registration day is already at capacity
474	     */
475	    private void assertDailyCapacity(Owner owner) {
476	        LocalDate date = owner.getRegistrationDate();
477	        if (date == null) {
478	            return;
479	        }
480	        if (countOwnersRegisteredOn(date) >= DAILY_OWNER_LIMIT) {
481	            throw new DailyOwnerLimitException(date, DAILY_OWNER_LIMIT);
482	        }
483	    }
484	
485	    private long countOwnersRegisteredOn(LocalDate date) {
486	        return ownerRepository.findAll().stream()
487	                .filter(existing -> date.equals(existing.getRegistrationDate()))
488	                .count();
489	    }
490	
491	    private long countOwnersInCity(String city) {
492	        String normalized = normalizeHouseholdValue(city);
493	        return ownerRepository.findAll().stream()
494	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
495	                .count();
496	    }
497	
498	    /**
499	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
500	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
501	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
502	     * that already existed before this create.
503	     */
504	    private int countNamesakes(Owner owner) {
505	        String firstName = normalizeHouseholdValue(owner.getFirstName());
506	        String lastName = normalizeHouseholdValue(owner.getLastName());
507	        int count = 0;
508	        for (Owner existing : ownerRepository.findAll()) {
509	            if (!existing.getId().equals(owner.getId())
510	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
511	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
512	                count++;
513	            }
514	        }
515	        return count;
516	    }
517	
518	    private static String normalizeEmail(String email) {
519	        return email == null ? null : email.toLowerCase(Locale.ROOT);
520	    }
521	
522	    /**
523	     * Normalizes whichever address fields {@code owner} supplied and derives the effective flat
524	     * {@code address} from them. The structured form is preferred: when a non-blank
525	     * {@code addressLine1} is present, {@code address} is set to the normalized {@code addressLine1},
526	     * with a single space and the normalized {@code addressLine2} appended when {@code addressLine2}
527	     * is present. Otherwise the flat {@code address} is normalized in place (backward-compatible). The
528	     * structured fields are also stored in their normalized form. Because everything downstream reads
529	     * {@link Owner#getAddress()}, the household hash, postcode validation and locality all see the
530	     * structured value when present and fall back to the flat address otherwise.
531	     */
532	    private static void applyAddress(Owner owner) {
533	        String line1 = normalizeAddress(owner.getAddressLine1());
534	        String line2 = normalizeAddress(owner.getAddressLine2());
535	        owner.setAddressLine1(line1);
536	        owner.setAddressLine2(line2);
537	        if (line1 != null && !line1.isEmpty()) {
538	            String composed = (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
539	            owner.setAddress(composed);
540	        } else if (owner.getAddress() != null) {
541	            owner.setAddress(normalizeAddress(owner.getAddress()));
542	        }
543	    }
544	
545	    /** Common street-type abbreviations expanded during address normalization. */
546	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
547	        "ST", "STREET",
548	        "RD", "ROAD",
549	        "AVE", "AVENUE");
550	
551	    /**
552	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
553	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
554	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
555	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
556	     * form.
557	     */
558	    private static String normalizeAddress(String address) {
559	        if (address == null) {
560	            return null;
561	        }
562	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
563	        if (collapsed.isEmpty()) {
564	            return "";
565	        }
566	        String[] tokens = collapsed.split(" ");
567	        StringBuilder sb = new StringBuilder(collapsed.length());
568	        for (int i = 0; i < tokens.length; i++) {
569	            if (i > 0) {
570	                sb.append(' ');
571	            }
572	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
573	        }
574	        return sb.toString();
575	    }
576	
577	    private static String normalizeTelephone(String telephone) {
578	        return telephone == null ? null : E164Telephone.toE164(telephone);
579	    }
580	
581	    /**
582	     * Rejects saving {@code owner} when its whole {@link Owner#getIdentityKey() identity key} equals
583	     * that of another owner. This single check consolidates the former separate telephone, email and
584	     * household duplicate rules: because the normalized telephone is part of the key, two members of
585	     * the same household (same {@code householdId}) with different telephones have different keys and
586	     * are both allowed — only an exact full-key match is a duplicate.
587	     *
588	     * @throws DuplicateIdentityException if another owner already has the same identity key
589	     */
590	    private void assertIdentityUnique(Owner owner) {
591	        String identityKey = owner.getIdentityKey();
592	        for (Owner existing : ownerRepository.findAll()) {
593	            if (!existing.getId().equals(owner.getId()) && identityKey.equals(existing.getIdentityKey())) {
594	                throw new DuplicateIdentityException(identityKey);
595	            }
596	        }
597	    }
598	
599	    /**
600	     * Assigns {@code owner} its deterministic {@code householdId}: the first 12 upper-case hex
601	     * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}, so all
602	     * owners that share a normalized {@code lastName} and {@code postcode} automatically share the
603	     * same household. Left {@code null} when either the lastName or the postcode is absent, since a
604	     * household is keyed on both.
605	     */
606	    private void assignHouseholdId(Owner owner) {
607	        String lastName = normalizeHouseholdValue(owner.getLastName());
608	        String postcode = owner.getPostcode();
609	        if (lastName.isEmpty() || postcode == null || postcode.isBlank()) {
610	            owner.setHouseholdId(null);
611	            return;
612	        }
613	        owner.setHouseholdId(generateHouseholdId(lastName, postcode));
614	    }
615	
616	    /**
617	     * Rejects creating {@code owner} when another owner already belongs to the same household — i.e.
618	     * shares its computed {@code householdId} (same normalized {@code lastName} and {@code postcode}).
619	     * Because the household is keyed on those two fields, a second such owner is a household
620	     * duplicate unless it declares {@code sharesHousehold}, in which case it is admitted as a
621	     * declared household member (and, being declared, is never a suspected duplicate). No-op when the
622	     * owner has no household id.
623	     *
624	     * @throws HouseholdDuplicateException if another owner already shares the household and the owner
625	     *     did not declare {@code sharesHousehold}
626	     */
627	    private void assertHouseholdUnique(Owner owner) {
628	        String householdId = owner.getHouseholdId();
629	        if (householdId == null || householdId.isBlank() || owner.isSharesHousehold()) {
630	            return;
631	        }
632	        for (Owner existing : ownerRepository.findAll()) {
633	            if (!existing.getId().equals(owner.getId()) && householdId.equals(existing.getHouseholdId())) {
634	                throw new HouseholdDuplicateException(householdId);
635	            }
636	        }
637	    }
638	
639	    /**
640	     * Stamps {@code owner} with the number of owners sharing its {@code householdId} (see {@link
641	     * Owner#getHouseholdSize()}), so presentation code can derive the membership tier without
642	     * reaching into the data store. A {@code null} owner or one without a household id is left at
643	     * size 0.
644	     */
645	    private void populateHouseholdSize(Owner owner) {
646	        if (owner == null) {
647	            return;
648	        }
649	        String householdId = owner.getHouseholdId();
650	        if (householdId == null || householdId.isBlank()) {
651	            owner.setHouseholdSize(0);
652	            return;
653	        }
654	        int count = 0;
655	        for (Owner existing : ownerRepository.findAll()) {
656	            if (householdId.equals(existing.getHouseholdId())) {
657	                count++;
658	            }
659	        }
660	        owner.setHouseholdSize(count);
661	    }
662	
663	    /**
664	     * Stamps every owner in {@code owners} with its household size in a single pass over the data
665	     * store, so a list/page of owners is counted without a per-owner query.
666	     *
667	     * @see #populateHouseholdSize(Owner)
668	     */
669	    private void populateHouseholdSizes(Collection<Owner> owners) {
670	        if (owners.isEmpty()) {
671	            return;
672	        }
673	        Map<String, Integer> sizes = new HashMap<>();
674	        for (Owner existing : ownerRepository.findAll()) {
675	            String householdId = existing.getHouseholdId();
676	            if (householdId != null && !householdId.isBlank()) {
677	                sizes.merge(householdId, 1, Integer::sum);
678	            }
679	        }
680	        for (Owner owner : owners) {
681	            String householdId = owner.getHouseholdId();
682	            owner.setHouseholdSize(householdId == null ? 0 : sizes.getOrDefault(householdId, 0));
683	        }
684	    }
685	
686	    /**
687	     * Derives the deterministic {@code householdId} from the normalized {@code lastName} and
688	     * {@code postcode}: the first 12 upper-case hex characters of SHA-256 over
689	     * {@code lastName + '|' + postcode}, so all owners in the same household share the same
690	     * identifier.
691	     */
692	    private static String generateHouseholdId(String lastName, String postcode) {
693	        return sha256UpperHex(lastName + "|" + postcode, 12);
694	    }
695	
696	    /**
697	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
698	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
699	     */
700	    private static String normalizeHouseholdValue(String value) {
701	        if (value == null) {
702	            return "";
703	        }
704	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
705	    }
706	
707	    @Override
708	    @Transactional(readOnly = true)
709	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
710	        Collection<Owner> owners = ownerRepository.findByLastName(lastName);
711	        populateHouseholdSizes(owners);
712	        return owners;
713	    }
714	
715	    @Override
716	    @Transactional(readOnly = true)
717	    public Collection<Visit> findVisitsByPetId(int petId) {
718	        return visitRepository.findByPetId(petId);
719	    }
720	
721	    @Override
722	    @Transactional(readOnly = true)
723	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
724	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
725	    }
726	
727	    private <T> T findEntityById(Supplier<T> supplier) {
728	        try {
729	            return supplier.get();
730	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
731	            // Just ignore not found exceptions for Jdbc/Jpa realization
732	            return null;
733	        }
734	    }
735	
736	}
